def logical(raw, *, parameter_lists=None, signature_suffixes=None, parameter_names=None):
    """Admit original raw bytes before expanding compact metadata."""
    return logical_parsed(_wire.decode_wire(raw), parameter_lists=parameter_lists,
                          signature_suffixes=signature_suffixes, parameter_names=parameter_names)


def logical_parsed(entries, *, parameter_lists=None, signature_suffixes=None, parameter_names=None):
    """Compare trusted parsed metadata under the complete decoded limits.

    This route cannot establish raw byte size, duplicate keys or number spelling.
    Saved files and browser input must enter through ``logical`` instead.
    """
    if parameter_lists is None:
        parameter_lists = COMPACT_PARAMETER_LISTS
    if signature_suffixes is None:
        signature_suffixes = COMPACT_SIGNATURE_SUFFIXES
    if parameter_names is None:
        parameter_names = COMPACT_PARAMETER_NAMES
    if type(entries) is dict:
        entries = _wire.decode_parsed_wire(entries)
    if type(entries) is not list or len(entries) > _wire.MAX_ENTRIES:
        raise ValueError("Expected bounded logical catalogue entries")
    entries = deepcopy(entries)
    result = {}
    for item in entries:
        compact_signature = "signature" not in item and str(item.get("s", "")).startswith("(")
        if "r" in item:
            legacy = item.pop("r")
            if "returns" not in item:
                item["returns"] = ("openecon." + legacy[1:]
                                   if isinstance(legacy, str) and legacy.startswith("~") else legacy)
        for short, full in {"n": "name", "s": "signature", "d": "description",
                            "p": "parameters", "r": "returns", "k": "kind"}.items():
            if short in item:
                item.setdefault(full, item.pop(short))
        if item["name"].startswith("~"):
            item["name"] = "openecon." + item["name"][1:]
        if compact_signature:
            item["signature"] = item["name"].rsplit(".", 1)[-1] + item["signature"]
        if "R" in item:
            item.setdefault("returns", "openecon." + item.pop("R"))
        if "T" in item:
            token = item.pop("T")
            if "returns" not in item:
                types = {0: "openecon.TableSet", 1: "openecon.ResultBundle", 2: "openecon.DataFrame"}
                if type(token) is not int or token not in types:
                    raise ValueError("Compact return type needs a recognized integer token")
                item["returns"] = types[token]
        if "S" in item:
            suffix = item.pop("S")
            if "signature" not in item:
                if not isinstance(suffix, str) or not suffix.startswith("("):
                    raise ValueError("Compact signature needs a parenthesized suffix")
                item["signature"] = item["name"].rsplit(".", 1)[-1] + suffix
        if "I" in item:
            token = item.pop("I")
            if "signature" not in item:
                if type(token) is not int or not 0 <= token < len(signature_suffixes):
                    raise ValueError("Compact signature needs a recognized integer token")
                item["signature"] = item["name"].rsplit(".", 1)[-1] + signature_suffixes[token]
        item["kind"] = {"m": "method", "c": "class"}.get(item.get("kind"), item.get("kind", "function"))
        if item["kind"] == "method":
            item.setdefault("owner", item["name"].rsplit(".", 1)[0])
        if "P" in item:
            token = item.pop("P")
            if "parameters" not in item:
                if type(token) is not int or not 0 <= token < len(parameter_lists):
                    raise ValueError("Compact parameters need a recognized integer token")
                item["parameters"] = deepcopy(parameter_lists[token])
        for parameter_index, parameter in enumerate(item["parameters"]):
            if not isinstance(parameter, dict):
                if (isinstance(parameter, bool) or not isinstance(parameter, (int, float))
                        or not 0 <= parameter < len(COMPACT_PARAMETER_RECORDS)
                        or not math.isfinite(parameter) or parameter != int(parameter)
                        or (parameter == 0 and math.copysign(1, parameter) < 0)):
                    raise ValueError("Compact parameter record needs a recognized integer token")
                parameter = deepcopy(COMPACT_PARAMETER_RECORDS[int(parameter)])
                item["parameters"][parameter_index] = parameter
            for short, full in {"n": "name", "d": "description", "v": "default",
                                "c": "choices", "a": "annotation", "k": "kind", "t": "kind"}.items():
                if short in parameter:
                    value = parameter.pop(short)
                    if short == "n" and "name" not in parameter and not isinstance(value, str):
                        if (isinstance(value, bool) or not isinstance(value, (int, float))
                                or not 0 <= value < len(parameter_names)
                                or not math.isfinite(value) or value != int(value)
                                or (value == 0 and math.copysign(1, value) < 0)):
                            raise ValueError("Compact parameter name needs a valid integer index")
                        value = parameter_names[int(value)]
                    if short == "v" and "default" not in parameter:
                        if value is None or isinstance(value, bool):
                            value = "None" if value is None else "True" if value else "False"
                        elif isinstance(value, (int, float)):
                            if (abs(value) > 2**53 - 1 or not math.isfinite(value)
                                    or value != int(value) or (value == 0 and math.copysign(1, value) < 0)):
                                raise ValueError("Compact numeric default needs a safe integer")
                            value = str(int(value))
                    parameter.setdefault(full, value)
            if "V" in parameter:
                literal = parameter.pop("V")
                if "default" not in parameter:
                    if type(literal) is not int or literal != 0:
                        raise ValueError("Compact default needs the integer zero None tag")
                    parameter["default"] = "None"
            if "B" in parameter:
                literal = parameter.pop("B")
                if "default" not in parameter:
                    if type(literal) is not int or literal not in (0, 1):
                        raise ValueError("Compact default needs the integer zero or one Boolean tag")
                    parameter["default"] = "True" if literal == 1 else "False"
            if "D" in parameter:
                literal = parameter.pop("D")
                if "default" not in parameter:
                    defaults = ("'raise'", '0.05', "'cpu'", '100000000', '50000000', "'drop'", '0.95', '0', 'DEFAULT_BYTES', 'DEFAULT_WORK', "'two-sided'", "'nonrobust'", "'constant'", '1000000', '2000000000', '100000')
                    if type(literal) is not int or not 0 <= literal < len(defaults):
                        raise ValueError("Compact default needs an integer fixed-literal tag from zero through fifteen")
                    parameter["default"] = defaults[literal]
            if "q" in parameter:
                quoted = parameter.pop("q")
                if "default" not in parameter:
                    if not isinstance(quoted, str) or any(char in quoted for char in ("'", "\\", "\n", "\r")):
                        raise ValueError("Compact quoted default needs an exact simple string")
                    parameter["default"] = "'" + quoted + "'"
            if "N" in parameter:
                literal = parameter.pop("N")
                if "default" not in parameter:
                    if type(literal) is not int or literal != 1:
                        raise ValueError("Legacy compact default needs the integer one None tag")
                    parameter["default"] = "None"
            parameter["kind"] = {"k": "keyword-only", "p": "positional-only",
                                 "*": "var-positional", "**": "var-keyword"}.get(
                                     parameter.get("kind"), parameter.get("kind", "positional-or-keyword"))
        if item["name"] in result:
            raise ValueError("Duplicate canonical API name.")
        result[item["name"]] = item
    _wire.admit_logical(list(result.values()))
    return result


def token_table_at(pin, name):
    """Read an exact pinned token layout without executing historical code.

    Unmerged branches can independently append different meanings at the same
    index. Decode each historical catalog using its own generator constants.
    """
    source = subprocess.check_output(
        ["git", "show", pin + ":scripts/generate_editor_api.py"], cwd=ROOT,
    )
    for node in ast.parse(source).body:
        if isinstance(node, ast.Assign) and any(
            isinstance(target, ast.Name) and target.id == name
            for target in node.targets
        ):
            return ast.literal_eval(node.value)
    return ()


def parameter_lists_at(pin):
    return token_table_at(pin, "STORED_PARAMETER_LISTS")


def signature_suffixes_at(pin):
    return token_table_at(pin, "STORED_SIGNATURE_SUFFIXES")


def parameter_names_at(pin):
    return token_table_at(pin, "STORED_PARAMETER_NAMES")


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--baseline-ref", required=True)
    parser.add_argument("--report", type=Path, required=True)
    args = parser.parse_args()
    pin = subprocess.check_output(["git", "rev-parse", "--verify", args.baseline_ref + "^{commit}"], cwd=ROOT, text=True).strip()
    before = subprocess.check_output(["git", "show", pin + ":web/src/editor-api.json"], cwd=ROOT)
    after = (ROOT / "web/src/editor-api.json").read_bytes()
    baseline_parameters = parameter_lists_at(pin)
    baseline_signatures = signature_suffixes_at(pin)
    baseline_names = parameter_names_at(pin)
    baseline = logical(before, parameter_lists=baseline_parameters,
                       signature_suffixes=baseline_signatures, parameter_names=baseline_names)
    current = logical(after)
    lost = [name for name, entry in baseline.items() if current.get(name) != entry]
    if lost:
        raise ValueError("Existing logical metadata changed: " + ", ".join(lost))
    report = {"status": "pass", "baseline_ref": pin,
              "retained_existing_entries": len(baseline), "current_entries": len(current),
              "existing_logical_metadata_equal": True,
              "new_entries": sorted(set(current) - set(baseline)),
              "baseline_sha256": hashlib.sha256(before).hexdigest(),
              "current_sha256": hashlib.sha256(after).hexdigest(),
              "current_bytes": len(after),
              "baseline_parameter_templates": len(baseline_parameters),
              "current_parameter_templates": len(COMPACT_PARAMETER_LISTS),
              "baseline_signature_templates": len(baseline_signatures),
              "current_signature_templates": len(COMPACT_SIGNATURE_SUFFIXES),
              "baseline_parameter_name_tokens": len(baseline_names),
              "current_parameter_name_tokens": len(COMPACT_PARAMETER_NAMES),
              "scope": "all existing signatures, defaults, choices, annotations, descriptions, returns, kinds and owners"}
    args.report.write_text(json.dumps(report, indent=2) + "\n")
    print(json.dumps({"status": "pass", "retained_existing_entries": len(baseline)}))


if __name__ == "__main__":
    main()
